CREATE TABLE "PlanScenario" ("id" TEXT NOT NULL,"planId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"shared" BOOLEAN NOT NULL DEFAULT false,"version" INTEGER NOT NULL DEFAULT 1,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PlanScenario_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioChange" ("id" TEXT NOT NULL,"scenarioId" TEXT NOT NULL,"issueId" TEXT NOT NULL,"baseVersion" INTEGER NOT NULL,"baseSnapshot" JSONB NOT NULL,"patch" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ScenarioChange_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioBaseline" ("id" TEXT NOT NULL,"scenarioId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"name" TEXT NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ScenarioBaseline_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScenarioPublish" ("id" TEXT NOT NULL,"scenarioId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"status" TEXT NOT NULL,"requestedChanges" JSONB NOT NULL,"appliedChanges" JSONB NOT NULL,"conflicts" JSONB NOT NULL,"rollbackSnapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ScenarioPublish_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PlanScenario_planId_name_key" ON "PlanScenario"("planId","name");CREATE INDEX "PlanScenario_planId_shared_archivedAt_idx" ON "PlanScenario"("planId","shared","archivedAt");CREATE INDEX "PlanScenario_ownerId_updatedAt_idx" ON "PlanScenario"("ownerId","updatedAt");
CREATE UNIQUE INDEX "ScenarioChange_scenarioId_issueId_key" ON "ScenarioChange"("scenarioId","issueId");CREATE INDEX "ScenarioChange_issueId_idx" ON "ScenarioChange"("issueId");
CREATE UNIQUE INDEX "ScenarioBaseline_scenarioId_name_key" ON "ScenarioBaseline"("scenarioId","name");CREATE INDEX "ScenarioBaseline_scenarioId_createdAt_idx" ON "ScenarioBaseline"("scenarioId","createdAt");CREATE INDEX "ScenarioPublish_scenarioId_createdAt_idx" ON "ScenarioPublish"("scenarioId","createdAt");
ALTER TABLE "PlanScenario" ADD CONSTRAINT "PlanScenario_planId_fkey" FOREIGN KEY ("planId") REFERENCES "PortfolioPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PlanScenario" ADD CONSTRAINT "PlanScenario_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ScenarioChange" ADD CONSTRAINT "ScenarioChange_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "PlanScenario"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScenarioBaseline" ADD CONSTRAINT "ScenarioBaseline_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "PlanScenario"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ScenarioBaseline" ADD CONSTRAINT "ScenarioBaseline_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ScenarioPublish" ADD CONSTRAINT "ScenarioPublish_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "PlanScenario"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "ScenarioPublish" ADD CONSTRAINT "ScenarioPublish_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
